  function svg(name, opts = {}) {
    const size = opts.size || 20;
    const cls = opts.class || '';
    // "-solid" suffix explicitly requests the filled variant (e.g. 'heart-solid', 'star-solid').
    // Bare names always resolve to the outline set first — several names (heart, star,
    // check-circle, bell-alert) exist in BOTH sets for the two visual states of that icon,
    // so outline must win by default or the solid variant would be unreachable.
    if (name.endsWith('-solid') && solid[name.slice(0, -6)]) {
      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor" class="${cls}"><path d="${solid[name.slice(0, -6)]}"/></svg>`;
    }
    if (outline[name]) {
      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="${cls}"><path d="${outline[name]}"/></svg>`;
    }
    if (solid[name]) {
      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor" class="${cls}"><path d="${solid[name]}"/></svg>`;
    }
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" class="${cls}"></svg>`;
  }

  return { html: svg, outline, solid };
